#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""fetch_crests.py — 高校校徽素材 + 品牌包维护脚本（学院汇报 PPT 技能 v2）

用途
----
1. 按内置清单下载/渲染 147 所「双一流」高校校徽 → ``assets/schools/crests/<slug>.png``
   （统一处理：去白底→透明、裁内容 bbox、留 8px 边、定高 ≤240px、≤200KB）；
2. 由清单里的官方 VI 色 / 校徽取色推导品牌包 → ``assets/schools/brand_packs.json``
   （自动校验 primary 与白底对比度 ≥4.5，不够则压暗）；
3. 自检：``--validate-only`` 校验已有校徽与品牌包；``--report`` 输出覆盖率与逐校来源。

用法
----
    python3 scripts/fetch_crests.py --report                 # 只报告现状（不联网）
    python3 scripts/fetch_crests.py --validate-only          # 自检（不联网）
    python3 scripts/fetch_crests.py --only qinghuadaxue      # 只处理一所
    python3 scripts/fetch_crests.py --all --write-packs      # 全量抓取并重写品牌包
    python3 scripts/fetch_crests.py --report --markdown out.md   # 报告另存 markdown

依赖：Pillow（必须）；cairosvg（SVG 转 PNG，推荐）；macOS 上无 cairosvg 时自动回落
``qlmanage -t``。网络仅在被要求抓取时使用；抓取仅用于个人/教学的模板匹配。

数据来源（逐校链接见 --report 输出）
- 校徽：github Magicdover/China-Universities-2026（SVG）、HeyHuazi/SVGLOGO（SVG）、
  xioajiumi/Chinese_Universities（PNG）、掌上高考 CDN static-data.gaokao.cn（备用）；
  少量取自学校官网（official-website）。
- 配色：yangxiake/university-design-db 记录的各校官方 VI 色卡 / 官网标识取样；
  无官方记录时由校徽取色（source=crest-estimated，verified=false）。
- 校训：同上（逐校保留来源），缺失留空。
"""

