# --------------------------------------------------------------------------- 颜色

def hex_to_rgb(s):
    s = (s or "").strip().lstrip("#")
    if len(s) == 3:
        s = "".join(c * 2 for c in s)
    if not re.fullmatch(r"[0-9a-fA-F]{6}", s or ""):
        raise ValueError("非法 HEX：%r" % s)
    return tuple(int(s[i:i + 2], 16) for i in (0, 2, 4))


def rgb_to_hex(rgb):
    return "#%02X%02X%02X" % tuple(max(0, min(255, int(round(v)))) for v in rgb)


def _lin(c):
    c = c / 255.0
    return c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4


def luminance(rgb):
    r, g, b = (_lin(v) for v in rgb)
    return 0.2126 * r + 0.7152 * g + 0.0722 * b


def contrast(a, b="#FFFFFF"):
    """WCAG 对比度（a/b 可为 #RRGGBB）"""
    la, lb = luminance(hex_to_rgb(a)), luminance(hex_to_rgb(b))
    hi, lo = max(la, lb), min(la, lb)
    return (hi + 0.05) / (lo + 0.05)


def mix(c1, c2, t):
    """c1 向 c2 混合 t（0..1）"""
    a, b = hex_to_rgb(c1), hex_to_rgb(c2)
    return rgb_to_hex(tuple(a[i] + (b[i] - a[i]) * t for i in range(3)))


def darken(c, t):
    return mix(c, "#000000", t)


def lighten(c, t):
    return mix(c, "#FFFFFF", t)


def rgb_to_hsl(rgb):
    r, g, b = [v / 255.0 for v in rgb]
    mx, mn = max(r, g, b), min(r, g, b)
    l = (mx + mn) / 2
    if mx == mn:
        return 0.0, 0.0, l
    d = mx - mn
    s = d / (2 - mx - mn) if l > 0.5 else d / (mx + mn)
    if mx == r:
        h = ((g - b) / d) % 6
    elif mx == g:
        h = (b - r) / d + 2
    else:
        h = (r - g) / d + 4
    return h * 60.0, s, l


def hsl_to_rgb(h, s, l):
    h = h % 360
    c = (1 - abs(2 * l - 1)) * s
    x = c * (1 - abs((h / 60.0) % 2 - 1))
    m = l - c / 2
    seg = int(h // 60) % 6
    r, g, b = [(c, x, 0), (x, c, 0), (0, c, x), (0, x, c), (x, 0, c), (c, 0, x)][seg]
    return tuple(round((v + m) * 255) for v in (r, g, b))


def ensure_contrast(color, bg="#FFFFFF", min_ratio=4.5):
    """保证前景色对白底对比度 ≥ min_ratio：不够就压暗（保持色相/饱和度）"""
    try:
        cur = color
        if contrast(cur, bg) >= min_ratio:
            return cur
        h, s, l = rgb_to_hsl(hex_to_rgb(cur))
        for i in range(1, 41):
            nl = max(0.0, l - i * 0.02)
            cand = rgb_to_hex(hsl_to_rgb(h, s, nl))
            if contrast(cand, bg) >= min_ratio:
                return cand
        return "#1A1A1A"
    except ValueError:
        return "#1A1A1A"


def derive_accent(primary, secondary=""):
    """辅助色：优先用官方辅助色；否则主色提亮一档（亮/饱和），并保证对白 ≥3.0"""
    if secondary:
        try:
            c = secondary
            if contrast(c, "#FFFFFF") >= 3.0 and color_distance(c, primary) > 28:
                return c
            if contrast(c, "#FFFFFF") < 3.0:
                fixed = ensure_contrast(c, "#FFFFFF", 3.0)
                if color_distance(fixed, primary) > 28:
                    return fixed
        except ValueError:
            pass
    h, s, l = rgb_to_hsl(hex_to_rgb(primary))
    for dl in (0.10, 0.08, 0.12, 0.06, 0.14, 0.16):
        cand = rgb_to_hex(hsl_to_rgb(h, min(1.0, s + 0.02), min(0.72, l + dl)))
        if contrast(cand, "#FFFFFF") >= 3.0 and color_distance(cand, primary) > 16:
            return cand
    return mix(primary, "#FFFFFF", 0.22)


def color_distance(c1, c2):
    """粗略感知距离（加权 RGB，够用来判断“是否太接近”）"""
    a, b = hex_to_rgb(c1), hex_to_rgb(c2)
    dr, dg, db = (a[0] - b[0]) * 0.3, (a[1] - b[1]) * 0.59, (a[2] - b[2]) * 0.11
    return math.sqrt(dr * dr + dg * dg + db * db)


def sample_primary_from_image(im):
    """从校徽图取主色：忽略透明/近白/近黑/低饱和像素，取高频色簇"""
    if im.mode != "RGBA":
        im = im.convert("RGBA")
    small = im.copy()
    small.thumbnail((160, 160))
    buckets = {}
    for r, g, b, a in small.getdata():
        if a < 180:
            continue
        h, s, l = rgb_to_hsl((r, g, b))
        if l > 0.90 or l < 0.08 or s < 0.18:
            continue
        key = (r // 24, g // 24, b // 24)
        rec = buckets.setdefault(key, [0, 0, 0, 0])
        rec[0] += r
        rec[1] += g
        rec[2] += b
        rec[3] += 1
    if not buckets:
        return None
    best = max(buckets.values(), key=lambda v: v[3])
    n = best[3]
    return rgb_to_hex((best[0] / n, best[1] / n, best[2] / n))


def hue_distance(c1, c2):
    """色相角距离（0~180）"""
    h1 = rgb_to_hsl(hex_to_rgb(c1))[0]
    h2 = rgb_to_hsl(hex_to_rgb(c2))[0]
    d = abs(h1 - h2) % 360
    return d if d <= 180 else 360 - d


def _saturation(color):
    try:
        return rgb_to_hsl(hex_to_rgb(color))[1]
    except ValueError:
        return 0.0


def _lightness(color):
    try:
        return rgb_to_hsl(hex_to_rgb(color))[2]
    except ValueError:
        return 0.0


def resolve_primary(entry, crest_img, warn):
    """确定 primary，优先级：
    1) 官方数字 VI 色（verified=true）
    2) 校方网页明确公布的 HEX
    3) 官方 VI 印刷色 CMYK（ICC→sRGB 近似）
    4) 官网标识取样（明度/饱和度合理时）
    5) 校徽取色（crest-estimated）
    6) 中性深蓝兜底
    """
    col = entry.get("color") or {}
    method = col.get("method") or ""
    recorded = col.get("value") or ""
    cmyk = col.get("official_cmyk") or {}
    sampled = sample_primary_from_image(crest_img) if crest_img is not None else None
    verified = False
    source = ""
    primary = ""

    def _src(kind, label="", url=""):
        txt = kind
        if label:
            txt += "（%s）" % label
        if url:
            txt += "｜" + _domain(url)
        return txt

    # 官网取样是否可信：不要太浅、不要灰
    sample_reliable = bool(recorded) and _lightness(recorded) <= 0.76 and _saturation(recorded) >= 0.20

    if method == "official_vi" and recorded:
        primary, verified = recorded, True
        source = _src("官方 VI 标准色", col.get("label") or "", col.get("source_url") or "")
    elif col.get("declared_hex") and recorded:
        primary = recorded
        source = _src("校方网页公布的 WEB/HEX 色值", col.get("label") or "", col.get("source_url") or "")
    elif cmyk.get("rgb"):
        cand = cmyk["rgb"]
        if sampled and hue_distance(cand, sampled) > 80:
            primary = sampled
            source = "校徽取色（crest-estimated）"
            warn.append("官方印刷色与校徽主色色相冲突，取校徽色以保持版式一致")
        else:
            primary = cand
            source = _src("官方 VI 印刷标准色 CMYK %s（ICC→sRGB 近似）" %
                          "/".join(str(v) for v in cmyk.get("cmyk") or []),
                          cmyk.get("label") or "")
    elif method == "crest_manual" and recorded:
        primary = recorded
        source = _src("校徽取色（人工选定，crest-estimated）", col.get("label") or "")
    elif method == "manual_derived" and sample_reliable:
        primary = recorded
        source = _src("官网标识取样", col.get("label") or "", col.get("source_url") or "")
    elif sampled:
        primary = sampled
        source = "校徽取色（crest-estimated）"
    elif recorded and method in ("badge_sample", "crest_estimate"):
        primary = recorded
        source = "校徽取色（crest-estimated，记录值）"
    elif recorded:
        primary = recorded
        source = "旧记录色（来源无法复核，兜底）"
        warn.append("主色来源不可靠，使用旧记录值")
    else:
        primary = DEFAULT_PRIMARY
        source = "中性配色（无可信主色）"
        warn.append("无可信主色，已用中性深蓝")

    primary = ensure_contrast(primary, "#FFFFFF", 4.5)
    sec = ""
    if col.get("secondary") and col.get("secondary_method") in ("official_vi", "manual_derived"):
        sec = col["secondary"]
    accent = derive_accent(primary, sec)
    pack_colors = OrderedDict([
        ("primary", primary),
        ("accent", accent),
        ("deep", darken(primary, 0.25)),
        ("soft", lighten(primary, 0.92)),
        ("ink", INK),
    ])
    return pack_colors, source, verified


def _domain(url):
    try:
        u = urllib.parse.urlparse(url)
        return u.netloc or url
    except Exception:  # noqa: BLE001
        return url


# --------------------------------------------------------------------------- 图像

def _pil():
    try:
        from PIL import Image, ImageChops  # noqa: F401
        return Image
    except ImportError:
        sys.exit("缺少 Pillow：请用带 Pillow 的 Python 运行（如 anaconda3/bin/python3）")


DEAD_HOSTS = set()


class DownloadTimeout(Exception):
    pass


def _with_watchdog(seconds, fn, *a, **kw):
    """SIGALRM 看门狗：DNS 卡死/握手卡死也能中断（仅主线程可用）"""
    import signal

    def _handler(signum, frame):
        raise DownloadTimeout("超时 %ss" % seconds)

    old = signal.signal(signal.SIGALRM, _handler)
    signal.alarm(int(seconds))
    try:
        return fn(*a, **kw)
    finally:
        signal.alarm(0)
        signal.signal(signal.SIGALRM, old)


def download(url, cache_dir, name=None, quiet=False):
    """带缓存/看门狗/失败域名黑名单的下载，返回本地路径；失败抛异常"""
    os.makedirs(cache_dir, exist_ok=True)
    host = _domain(url)
    if host in DEAD_HOSTS:
        raise IOError("域名已标记不可达，跳过：%s" % host)
    key = name or (re.sub(r"[^A-Za-z0-9._-]", "_", urllib.parse.urlparse(url).path)[-60:]
                   or "download")
    ext = os.path.splitext(urllib.parse.urlparse(url).path)[1] or ".bin"
    if not key.lower().endswith(ext.lower()):
        key += ext
    dest = os.path.join(cache_dir, key)
    if os.path.isfile(dest) and os.path.getsize(dest) > 0:
        return dest
    last = None
    tries = 2 if ("github" in host or "wikipedia" in host or "gaokao" in host) else 1
    for attempt in range(tries):
        try:
            def _do():
                req = urllib.request.Request(url, headers={"User-Agent": UA})
                with urllib.request.urlopen(req, timeout=DOWNLOAD_TIMEOUT) as r:
                    return r.read()
            data = _with_watchdog(DOWNLOAD_TIMEOUT, _do)
            if not data:
                raise IOError("空响应")
            with open(dest, "wb") as f:
                f.write(data)
            if not quiet:
                print("    下载成功 %d 字节 ← %s" % (len(data), host))
            time.sleep(POLITE_DELAY)
            return dest
        except Exception as e:  # noqa: BLE001
            last = e
            if isinstance(e, DownloadTimeout) or "timed out" in str(e) or "handshake" in str(e):
                DEAD_HOSTS.add(host)
                break
            if isinstance(e, urllib.error.HTTPError):
                break
            time.sleep(1.0)
    if "github" not in host and host not in DEAD_HOSTS:
        DEAD_HOSTS.add(host)
    raise IOError("下载失败 %s：%s" % (url, last))


def _has_cairosvg():
    try:
        import cairosvg  # noqa: F401
        return True
    except Exception:  # noqa: BLE001
        return False


def rasterize(path, target_px=1200):
    """SVG/位图 → RGBA PIL.Image"""
    Image = _pil()
    ext = os.path.splitext(path)[1].lower()
    if ext in (".svg", ".svgz") or open(path, "rb").read(300).lstrip().startswith(b"<svg"):
        if _has_cairosvg():
            import cairosvg
            png = cairosvg.svg2png(url=path, output_width=target_px)
            return Image.open(io.BytesIO(png)).convert("RGBA")
        # macOS 回落：qlmanage 缩略图
        tmpd = tempfile.mkdtemp(prefix="crest-ql-")
        try:
            subprocess.run(["qlmanage", "-t", "-s", str(target_px), "-o", tmpd, path],
                           check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            outs = [os.path.join(tmpd, f) for f in os.listdir(tmpd)]
            if not outs:
                raise IOError("qlmanage 未产出缩略图")
            return Image.open(outs[0]).convert("RGBA")
        finally:
            shutil.rmtree(tmpd, ignore_errors=True)
    im = Image.open(path)
    if im.mode not in ("RGBA", "RGB", "LA", "P"):
        im = im.convert("RGBA")
    im = im.convert("RGBA")
    # 过小的位图适度放大，避免细线丢失
    if max(im.size) < target_px:
        ratio = target_px / float(max(im.size))
        im = im.resize((max(1, int(im.width * ratio)), max(1, int(im.height * ratio))),
                       Image.LANCZOS)
    return im


def strip_white_bg(im, tol=238):
    """从四边泛洪去白/浅灰底 → 透明；内部被围住的白色保留。
    边框若是浅色（含截图式浅灰框），以边框主色为参考色泛洪。"""
    from collections import deque
    im = im.copy()
    w, h = im.size
    px = im.load()

    border = [(x, 0) for x in range(w)] + [(x, h - 1) for x in range(w)] + \
             [(0, y) for y in range(h)] + [(w - 1, y) for y in range(h)]

    def _light(p):
        return p[3] > 0 and (0.299 * p[0] + 0.587 * p[1] + 0.114 * p[2]) / 255.0 > 0.78

    light_border = [px[x, y] for x, y in border if _light(px[x, y])]
    if not light_border:
        return im
    ref = None
    if len(light_border) >= 0.3 * len(border):
        rs = sorted(p[0] for p in light_border)
        gs = sorted(p[1] for p in light_border)
        bs = sorted(p[2] for p in light_border)
        ref = (rs[len(rs) // 2], gs[len(gs) // 2], bs[len(bs) // 2])

    def near_white(p):
        if p[3] == 0:
            return False
        if ref is not None:
            d = abs(p[0] - ref[0]) + abs(p[1] - ref[1]) + abs(p[2] - ref[2])
            if d <= 60:
                return True
        return p[0] >= tol and p[1] >= tol and p[2] >= tol
    seen = bytearray(w * h)
    dq = deque()
    for x, y in border:
        if near_white(px[x, y]) and not seen[y * w + x]:
            seen[y * w + x] = 1
            dq.append((x, y))
    while dq:
        x, y = dq.popleft()
        r, g, b, _a = px[x, y]
        px[x, y] = (r, g, b, 0)
        for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
            if 0 <= nx < w and 0 <= ny < h and not seen[ny * w + nx] and near_white(px[nx, ny]):
                seen[ny * w + nx] = 1
                dq.append((nx, ny))
    return im


def crop_bbox(im, alpha_floor=12):
    a = im.split()[3].point(lambda v: 255 if v > alpha_floor else 0)
    box = a.getbbox()
    if not box:
        return None
    return im.crop(box)


def light_edge_ratio(im):
    """内缩 8px 的边框上“不透明且浅色”像素占比；白底块/截图框会很高"""
    w, h = im.size
    px = im.load()
    pts = []
    inset = 8 if min(w, h) > 24 else 2
    for x in range(inset, w - inset):
        pts.append(px[x, inset])
        pts.append(px[x, h - 1 - inset])
    for y in range(inset, h - inset):
        pts.append(px[inset, y])
        pts.append(px[w - 1 - inset, y])
    if not pts:
        return 0.0
    light = sum(1 for p in pts if p[3] > 200 and min(p[:3]) >= 200)
    return light / float(len(pts))


def ink_stats(im):
    """返回 (不透明覆盖率, 内圈覆盖率, 四角是否透明)"""
    w, h = im.size
    a = im.split()[3]
    hist = a.histogram()
    opaque = sum(hist[40:]) / float(w * h)
    # 四角（各 12% 方块）透明度
    box = max(2, int(min(w, h) * 0.12))
    corners = [(0, 0), (w - box, 0), (0, h - box), (w - box, h - box)]
    filled = 0
    px = im.load()
    for cx, cy in corners:
        cnt = 0
        for x in range(cx, cx + box, max(1, box // 6)):
            for y in range(cy, cy + box, max(1, box // 6)):
                if px[x, y][3] > 40:
                    cnt += 1
        if cnt > 2:
            filled += 1
    return opaque, filled


def normalize_crest(im, pad=PAD):
    """去白底→裁剪→定高→留边。返回 (新图, 统计 dict)"""
    Image = _pil()
    im = strip_white_bg(im)
    cropped = crop_bbox(im)
    if cropped is None:
        raise ValueError("图像全透明/全白，无内容")
    im = cropped
    w, h = im.size
    if w < 8 or h < 8:
        raise ValueError("内容过小 %dx%d" % (w, h))
    aspect = w / float(h)
    if aspect < 0.58 or aspect > 1.72:
        raise ValueError("非校徽比例（%dx%d，宽高比 %.2f）" % (w, h, aspect))
    opaque, corner_filled = ink_stats(im)
    if opaque < 0.02:
        raise ValueError("内容几乎全透明（覆盖率 %.3f）" % opaque)
    edge = light_edge_ratio(im)
    if edge > 0.30:
        raise ValueError("白底块/背景框（边缘浅色占比 %.2f）" % edge)
    # 统一视觉重量：线条图给满高，实心图略缩小
    if opaque >= 0.62 or corner_filled >= 3:
        content_h = 208
    else:
        content_h = 224
    scale = content_h / float(h)
    nw, nh = max(1, int(round(w * scale))), content_h
    im = im.resize((nw, nh), Image.LANCZOS)
    canvas = Image.new("RGBA", (nw + 2 * pad, nh + 2 * pad), (0, 0, 0, 0))
    canvas.paste(im, (pad, pad), im)
    return canvas, {"opaque": round(opaque, 3), "corner_filled": corner_filled,
                    "content_h": content_h, "src_aspect": round(aspect, 3)}


def save_png(im, path):
    """保存 PNG（≤200KB：逐步降色深/量化）"""
    im.save(path, "PNG", optimize=True)
    if os.path.getsize(path) <= MAX_PNG_BYTES:
        return
    im2 = im.convert("P", palette=0, colors=64)
    im2.save(path, "PNG", optimize=True)
    if os.path.getsize(path) <= MAX_PNG_BYTES:
        return
    im.convert("P", palette=0, colors=32).save(path, "PNG", optimize=True)


def validate_crest(path):
    """校验单张校徽，返回 (ok, issues, stats)"""
    Image = _pil()
    issues = []
    stats = {}
    if not os.path.isfile(path):
        return False, ["文件不存在"], stats
    size = os.path.getsize(path)
    stats["bytes"] = size
    try:
        im = Image.open(path)
        im.load()
    except Exception as e:  # noqa: BLE001
        return False, ["PIL 无法打开：%s" % e], stats
    if im.mode != "RGBA":
        im = im.convert("RGBA")
    w, h = im.size
    stats.update(w=w, h=h, mode=im.mode)
    if w < 64 or h < 64:
        issues.append("尺寸过小 %dx%d（需 ≥64）" % (w, h))
    if h > MAX_HEIGHT:
        issues.append("高度 %d > %d" % (h, MAX_HEIGHT))
    if size > MAX_PNG_BYTES:
        issues.append("文件 %.0fKB > 200KB" % (size / 1024.0))
    aspect = w / float(h)
    stats["aspect"] = round(aspect, 3)
    if aspect < 0.58 or aspect > 1.72:
        issues.append("宽高比异常 %.2f" % aspect)
    # 空白检测：合成到白底后灰度 stddev
    a = im.split()[3]
    opaque_ratio = sum(a.histogram()[40:]) / float(w * h)
    stats["opaque"] = round(opaque_ratio, 3)
    if opaque_ratio < 0.03:
        issues.append("几乎全透明")
    gray = Image.composite(im.convert("L"), Image.new("L", im.size, 255), a)
    hist = gray.histogram()
    total = float(sum(hist)) or 1.0
    mean = sum(i * c for i, c in enumerate(hist)) / total
    var = sum((i - mean) ** 2 * c for i, c in enumerate(hist)) / total
    stddev = math.sqrt(var)
    stats["stddev"] = round(stddev, 2)
    if stddev <= 8:
        issues.append("近空白（stddev=%.1f，需 >8）" % stddev)
    # 白底方块检测：边框几乎全是纯白不透明像素
    border_white = 0
    border_total = 0
    bp = im.load()
    for x in range(w):
        for y in (0, h - 1):
            p = bp[x, y]
            border_total += 1
            if p[3] > 250 and p[0] > 250 and p[1] > 250 and p[2] > 250:
                border_white += 1
    for y in range(h):
        for x in (0, w - 1):
            p = bp[x, y]
            border_total += 1
            if p[3] > 250 and p[0] > 250 and p[1] > 250 and p[2] > 250:
                border_white += 1
    ratio = border_white / float(border_total or 1)
    stats["white_border"] = round(ratio, 3)
    if ratio > 0.9:
        issues.append("疑似白底方块（边框 %.0f%% 纯白）" % (ratio * 100))
    ledge = light_edge_ratio(im)
    stats["light_edge"] = round(ledge, 3)
    if ledge > 0.30:
        issues.append("疑似白底块/截图背景框（内缩边缘浅色 %.0f%%）" % (ledge * 100))
    return (not issues), issues, stats


# --------------------------------------------------------------------------- 抓取

def _xiao_source(entry):
    """xioajiumi 数据集（打包为 logo.zip）：返回 (zip_url, member_name)"""
    for c in entry.get("crests") or []:
        if c.get("xiao_member"):
            return c.get("xiao_zip"), c["xiao_member"]
    return None, None


def fetch_one(slug, entry, cache_dir, quiet=False):
    """按候选优先级抓取并处理一所学校的校徽；返回 dict"""
    Image = _pil()
    os.makedirs(CREST_DIR, exist_ok=True)
    out_path = os.path.join(CREST_DIR, slug + ".png")
    errors = []
    used = None
    candidates = list(entry.get("crests") or [])
    zip_url, member = _xiao_source(entry)
    for c in candidates:
        url = c.get("url")
        if not url:
            continue
        try:
            if c.get("kind") == "xiao-zip":
                zpath = download(zip_url, cache_dir, name="xiao-logo.zip", quiet=quiet)
                im = _read_zip_member(zpath, member)
            else:
                path = download(url, cache_dir, quiet=quiet)
                im = rasterize(path)
            im, stat = normalize_crest(im)
            save_png(im, out_path)
            ok, issues, vstat = validate_crest(out_path)
            if not ok:
                raise ValueError("校验不过：" + "；".join(issues))
            used = dict(c, stats={**stat, **vstat})
            break
        except Exception as e:  # noqa: BLE001
            errors.append("%s: %s" % (c.get("kind") or url, e))
            continue
    if used is None:
        return {"ok": False, "slug": slug, "name": entry.get("name"),
                "errors": errors, "path": None}
    return {"ok": True, "slug": slug, "name": entry.get("name"), "path": out_path,
            "source": used, "errors": errors}


def _read_zip_member(zip_path, member):
    """从 xioajiumi logo.zip 读指定校名 PNG（UTF-8 名）"""
    import zipfile
    Image = _pil()
    if not member:
        raise ValueError("缺少 zip 成员名")
    with zipfile.ZipFile(zip_path) as z:
        names = z.namelist()
        hit = next((n for n in names if os.path.basename(n) == member), None)
        if hit is None:
            # 全角/半角括号互认
            alt = member.replace("(", "（").replace(")", "）")
            hit = next((n for n in names if os.path.basename(n) == alt), None)
        if hit is None:
            raise IOError("zip 内找不到成员 %s" % member)
        return Image.open(io.BytesIO(z.read(hit))).convert("RGBA")


def fetch_all(only=None, force=False, quiet=False, cache_dir=None):
    cache_dir = cache_dir or DEFAULT_CACHE
    results = []
    schools = MANIFEST["schools"]
    if only:
        targets = [s for s in schools if s["slug"] in only or s["name"] in only]
        missing = set(only) - {s["slug"] for s in targets} - {s["name"] for s in targets}
        for m in missing:
            print("!! 清单里没有：%s" % m)
    else:
        targets = schools
    for i, entry in enumerate(targets, 1):
        slug = entry["slug"]
        out_path = os.path.join(CREST_DIR, slug + ".png")
        if os.path.isfile(out_path) and not force:
            ok, issues, _ = validate_crest(out_path)
            if ok:
                print("[%3d/%3d] %-6s %-14s 已存在且校验通过，跳过" %
                      (i, len(targets), slug, entry["name"]))
                results.append({"ok": True, "slug": slug, "name": entry["name"],
                                "path": out_path, "skipped": True})
                continue
        print("[%3d/%3d] %-6s %-14s 抓取中…" % (i, len(targets), slug, entry["name"]))
        r = fetch_one(slug, entry, cache_dir, quiet=quiet)
        if r["ok"]:
            print("        → %s (%d×%d, %.0fKB) 源=%s" %
                  (os.path.basename(r["path"]), r["source"]["stats"]["w"],
                   r["source"]["stats"]["h"], r["source"]["stats"]["bytes"] / 1024.0,
                   r["source"].get("kind")))
        else:
            print("        ✗ 失败：%s" % ("；".join(r["errors"][:3]) or "无可用源"))
        results.append(r)
    return results


# --------------------------------------------------------------------------- 品牌包

SKIN_HINT = "academic"

CREST_KIND_LABEL = {
    "magic": "Magicdover/China-Universities-2026 校徽集",
    "svglogo": "HeyHuazi/SVGLOGO 校徽集",
    "official-badge": "学校官网",
    "official-site": "学校官网",
    "xiao-zip": "xioajiumi/Chinese_Universities 校徽集",
    "eol-cdn": "掌上高考 CDN",
    "wikimedia": "Wikimedia Commons",
}


def decide_decor(crest_path):
    """按校徽形态选装饰语言：圆形→arc；实心方/盾→block；线条→minimal；其他→rule"""
    try:
        Image = _pil()
        with Image.open(crest_path) as im:
            im = im.convert("RGBA")
            w, h = im.size
            box = max(2, int(min(w, h) * 0.12))
            px = im.load()
            filled = 0
            for cx, cy in ((0, 0), (w - box, 0), (0, h - box), (w - box, h - box)):
                cnt = 0
                for x in range(cx, cx + box, max(1, box // 6)):
                    for y in range(cy, cy + box, max(1, box // 6)):
                        if px[x, y][3] > 40:
                            cnt += 1
                if cnt > 2:
                    filled += 1
            opaque = sum(im.split()[3].histogram()[40:]) / float(w * h)
            aspect = w / float(h)
            if filled >= 3:
                return "block"
            if filled == 0 and 0.82 <= aspect <= 1.22 and opaque >= 0.12:
                return "arc"
            if opaque < 0.24:
                return "minimal"
            return "rule"
    except Exception:  # noqa: BLE001
        return "rule"


def build_pack(slug, entry, crest_ok, crest_source_kind, decor=None, schools_index=None):
    """生成单校品牌包（dict）"""
    Image = _pil()
    crest_path = os.path.join(CREST_DIR, slug + ".png")
    crest_img = None
    if crest_ok and os.path.isfile(crest_path):
        try:
            crest_img = Image.open(crest_path).convert("RGBA")
        except Exception:  # noqa: BLE001
            crest_img = None
    warn = []
    colors, color_source, color_verified = resolve_primary(entry, crest_img, warn)

    school = entry["name"]
    school_en = entry.get("name_en") or ""
    if schools_index:
        ref = schools_index.get(slug) or schools_index.get(entry["name"])
        if ref:
            school = ref.get("name") or school
            school_en = ref.get("name_en") or school_en

    if crest_source_kind in ("official-badge", "official-site"):
        crest_source = "official-website"
    elif crest_source_kind == "wikimedia":
        crest_source = "wikimedia"
    elif crest_source_kind:
        crest_source = "dataset"
    else:
        crest_source = "estimated"

    motto = (entry.get("motto") or "").strip()
    pack = OrderedDict()
    pack["school"] = school
    pack["school_en"] = school_en
    pack["colors"] = colors
    pack["crest"] = ("crests/%s.png" % slug) if crest_ok else None
    pack["crest_kind"] = "image" if crest_ok else "text"
    pack["crest_source"] = crest_source
    pack["crest_verified"] = bool(crest_ok)
    pack["motto"] = motto
    pack["footer_left"] = motto
    pack["footer_right"] = school_en
    pack["decor"] = decor or "rule"
    pack["skin_hint"] = SKIN_HINT
    src = color_source
    if crest_ok:
        src += "；校徽：" + CREST_KIND_LABEL.get(crest_source_kind or "", crest_source_kind or "")
    pack["source"] = src
    pack["verified"] = bool(color_verified)
    return pack


def write_packs(packs):
    data = OrderedDict()
    for slug in sorted(packs):
        data[slug] = packs[slug]
    tmp = PACKS_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=1)
        f.write("\n")
    os.replace(tmp, PACKS_PATH)
    print("写出 %s（%d 所）" % (PACKS_PATH, len(data)))


def load_schools_index():
    if not os.path.isfile(SCHOOLS_PATH):
        return None
    try:
        data = json.load(open(SCHOOLS_PATH, encoding="utf-8"))
        arr = data.get("schools") if isinstance(data, dict) else data
        if isinstance(arr, list):
            return {x.get("slug") or x.get("name"): x for x in arr if isinstance(x, dict)}
    except Exception as e:  # noqa: BLE001
        print("!! schools.json 读取失败：%s" % e)
    return None


# --------------------------------------------------------------------------- 校验/报告

def validate_all(schools_index=None):
    """校验校徽 + 品牌包；返回 (failures, stats)"""
    Image = _pil()
    failures = []
    stats = {"total": len(MANIFEST["schools"]), "crest_ok": 0, "crest_missing": [],
             "packs": 0, "pack_issues": [], "verified_colors": 0, "motto": 0}
    for entry in MANIFEST["schools"]:
        slug = entry["slug"]
        path = os.path.join(CREST_DIR, slug + ".png")
        ok, issues, st = validate_crest(path)
        if ok:
            stats["crest_ok"] += 1
        else:
            stats["crest_missing"].append((slug, entry["name"], issues))
    packs = {}
    if os.path.isfile(PACKS_PATH):
        try:
            packs = json.load(open(PACKS_PATH, encoding="utf-8"))
        except Exception as e:  # noqa: BLE001
            failures.append("brand_packs.json 非法 JSON：%s" % e)
    stats["packs"] = len(packs)
    for slug, p in packs.items():
        try:
            cols = p["colors"]
            for k in ("primary", "accent", "deep", "soft", "ink"):
                v = cols.get(k)
                if k in ("primary", "accent") or v is not None:
                    if v:
                        hex_to_rgb(v)
            pr = cols.get("primary")
            if not pr:
                stats["pack_issues"].append((slug, "缺 primary"))
            else:
                c = contrast(pr, "#FFFFFF")
                if c < 4.5:
                    stats["pack_issues"].append((slug, "primary %s 对比度 %.2f < 4.5" % (pr, c)))
            ac = cols.get("accent")
            if ac and contrast(ac, "#FFFFFF") < 3.0:
                stats["pack_issues"].append((slug, "accent %s 对比度过低 %.2f" % (ac, contrast(ac, "#FFFFFF"))))
            if p.get("crest"):
                cp = os.path.join(ASSETS_DIR, p["crest"])
                if not os.path.isfile(cp):
                    stats["pack_issues"].append((slug, "crest 指向不存在：%s" % p["crest"]))
                elif not validate_crest(cp)[0]:
                    stats["pack_issues"].append((slug, "crest 未过校验：%s" % p["crest"]))
            if p.get("verified"):
                stats["verified_colors"] += 1
            if p.get("motto"):
                stats["motto"] += 1
            if schools_index is not None:
                ref = schools_index.get(slug)
                if ref is None:
                    stats["pack_issues"].append((slug, "slug 不在 schools.json"))
                elif ref.get("name") and ref["name"] != p.get("school"):
                    stats["pack_issues"].append(
                        (slug, "校名不一致：包=%s / schools.json=%s" % (p.get("school"), ref["name"])))
        except Exception as e:  # noqa: BLE001
            stats["pack_issues"].append((slug, "校验异常：%s" % e))
    if stats["pack_issues"]:
        failures.extend("%s：%s" % (s, m) for s, m in stats["pack_issues"][:40])
    return failures, stats


def report(markdown_path=None):
    Image = _pil()
    lines = []
    schools = MANIFEST["schools"]
    rows = []
    for e in schools:
        slug = e["slug"]
        path = os.path.join(CREST_DIR, slug + ".png")
        ok, issues, st = validate_crest(path)
        rows.append((e, ok, st, issues))
    n = len(schools)
    crest_ok = sum(1 for _, ok, _, _ in rows if ok)
    by_method = {}
    for e in schools:
        m = (e.get("color") or {}).get("method") or "?"
        by_method[m] = by_method.get(m, 0) + 1
    motto = sum(1 for e in schools if (e.get("motto") or "").strip())
    lines.append("# 校徽 / 品牌包覆盖报告")
    lines.append("")
    lines.append("- 范围：%s（%d 所）" % (MANIFEST.get("scope", ""), n))
    lines.append("- 清单版本：%s" % MANIFEST.get("generated_at", ""))
    lines.append("- 校徽可用：**%d / %d**（%.1f%%）" % (crest_ok, n, 100.0 * crest_ok / n))
    lines.append("- 校训有记录：%d / %d" % (motto, n))
    lines.append("- 主色口径：" + "，".join("%s %d 所" % (k, v) for k, v in sorted(by_method.items())))
    lines.append("")
    lines.append("## 逐校来源")
    lines.append("")
    lines.append("| # | 学校 | slug | 主色 | 色值口径 | 校徽来源 | 校徽状态 |")
    lines.append("|---|---|---|---|---|---|---|")
    for i, (e, ok, st, issues) in enumerate(rows, 1):
        col = e.get("color") or {}
        method = col.get("method") or ""
        if method == "official_vi":
            mdesc = "官方VI"
        elif method == "manual_derived":
            mdesc = "官网取色"
        elif method == "badge_sample":
            mdesc = "校徽取色"
        else:
            mdesc = "校徽取色"
        crests = e.get("crests") or []
        src = crests[0] if crests else {}
        src_txt = ""
        if src:
            url = src.get("url") or ""
            if src.get("kind") == "xiao-zip":
                src_txt = "xioajiumi/logo.zip"
            elif "Magicdover" in url:
                src_txt = "Magicdover/China-Universities-2026"
            elif "SVGLOGO" in url:
                src_txt = "HeyHuazi/SVGLOGO"
            elif "gaokao.cn" in url:
                src_txt = "掌上高考CDN"
            elif src.get("official"):
                src_txt = "学校官网"
            else:
                src_txt = _domain(url)
        issue_txt = "ok" if ok else "缺失：" + "；".join(issues[:1])
        lines.append("| %d | %s | %s | %s | %s | %s | %s |" % (
            i, e["name"], e["slug"], col.get("value") or "-", mdesc, src_txt or "-", issue_txt))
    text = "\n".join(lines) + "\n"
    print(text)
    if markdown_path:
        with open(markdown_path, "w", encoding="utf-8") as f:
            f.write(text)
        print("报告已写入 %s" % markdown_path)
    return text


# --------------------------------------------------------------------------- main

def main(argv=None):
    ap = argparse.ArgumentParser(
        description="校徽素材与品牌包维护（147 所双一流）",
        formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--only", nargs="+", metavar="SLUG", help="只处理指定 slug/校名")
    ap.add_argument("--all", action="store_true", help="抓取清单内全部学校校徽")
    ap.add_argument("--force", action="store_true", help="已存在也重新抓取")
    ap.add_argument("--validate-only", action="store_true", help="只校验已有产物（不联网）")
    ap.add_argument("--report", action="store_true", help="输出覆盖报告（不联网）")
    ap.add_argument("--markdown", metavar="PATH", help="报告另存 markdown")
    ap.add_argument("--write-packs", action="store_true", help="抓取后重写 brand_packs.json")
    ap.add_argument("--cache-dir", default=DEFAULT_CACHE, help="下载缓存目录")
    ap.add_argument("--quiet", action="store_true")
    args = ap.parse_args(argv)

    os.makedirs(CREST_DIR, exist_ok=True)
    schools_index = load_schools_index()

    if args.report or args.validate_only:
        failures, stats = validate_all(schools_index)
        print("=" * 66)
        print("清单：%d 所；校徽可用 %d，缺失 %d；品牌包 %d 条；verified 色 %d；校训 %d" % (
            stats["total"], stats["crest_ok"], len(stats["crest_missing"]),
            stats["packs"], stats["verified_colors"], stats["motto"]))
        if stats["crest_missing"]:
            print("\n缺校徽（%d）：" % len(stats["crest_missing"]))
            for slug, name, issues in stats["crest_missing"]:
                print("  - %-8s %-12s %s" % (slug, name, "；".join(issues[:2])))
        if stats["pack_issues"]:
            print("\n品牌包问题（%d 条，最多列 40）：" % len(stats["pack_issues"]))
            for slug, msg in stats["pack_issues"][:40]:
                print("  - %-8s %s" % (slug, msg))
        if args.report:
            report(args.markdown)
        if args.validate_only:
            ok = not failures and not stats["crest_missing"]
            print("\n自检结果：%s（%d 项失败）" % ("PASS" if ok else "FAIL", len(failures)))
            if failures:
                print("\n".join("  ✗ " + f for f in failures))
            return 0 if ok else 1
        return 0

    if not args.only and not args.all:
        if args.write_packs:
            results = []
        else:
            ap.print_help()
            print("\n提示：先用 --report 看现状，再 --all 抓取，或 --only <slug> 单校处理")
            return 2

    results = (fetch_all(only=args.only, force=args.force, quiet=args.quiet,
                         cache_dir=args.cache_dir)
               if (args.only or args.all) else [])
    ok = [r for r in results if r.get("ok")]
    bad = [r for r in results if not r.get("ok")]
    print("\n完成：成功 %d / %d" % (len(ok), len(results)))
    if bad:
        print("失败 %d 所：" % len(bad))
        for r in bad:
            print("  - %s %s" % (r["slug"], r["errors"][:2]))
    if args.write_packs:
        packs = {}
        for e in MANIFEST["schools"]:
            slug = e["slug"]
            path = os.path.join(CREST_DIR, slug + ".png")
            crest_ok = validate_crest(path)[0]
            kind = None
            res = next((r for r in results if r["slug"] == slug), None)
            if res and res.get("ok"):
                kind = res["source"].get("kind")
            elif os.path.isfile(path):
                kind = _infer_kind(e)
            packs[slug] = build_pack(slug, e, crest_ok, kind,
                                     decor=decide_decor(path) if crest_ok else "rule",
                                     schools_index=schools_index)
        write_packs(packs)
    return 0 if not bad else 1


def _infer_kind(entry):
    """已落盘校徽的实际来源：优先构建期记录的 crest_used，其次清单首选源"""
    if entry.get("crest_used"):
        return entry["crest_used"]
    for c in entry.get("crests") or []:
        return c.get("kind")
    return None


if __name__ == "__main__":
    sys.exit(main())
